    // ---- oscillation control ---------------------------------------------
    // A converged step can still be wrong: coarse dt against a fast reaction
    // makes the scheme alternate. Detect a sign-alternating triple in the
    // accepted states, then either rewind to the last restore point and
    // restart at dt/5 (discarding the samples already spoiled) or simply
    // continue at dt/5. Mirrors System::Solve's block step for step.
    struct RestorePoint {
        double t = 0, dt = 0;
        std::vector<double> storage, mass, limitFactor;
        std::vector<int> limited;
        unsigned used = 0;
        bool valid = false;
    };
    int  oscillationEvents() const      { return osc_events_; }
    int  oscillationReductions() const  { return osc_reductions_; }
    int  oscillationRelaxations() const { return osc_relaxations_; }
    bool oscillationGaveUp() const      { return osc_gave_up_; }
    // The solution order the interpreter uses: the flow states, then the
    // transport unknowns (System::GatherSolvedState).
    void gatherSolvedState(std::vector<double>& out) const {
        out.clear();
        for (int b = 0; b < N_STATES; ++b) out.push_back(solver_.storage(b));
        for (int i = 0; i < N_MASS; ++i) out.push_back(transport_.mass(i));
    }
    void saveRestorePoint() {
        rp_.storage.assign(N_STATES, 0.0); rp_.limited.assign(N_STATES, 0);
        rp_.limitFactor.assign(N_STATES, 1.0);
        rp_.mass.assign(N_MASS, 0.0);
        exportState(rp_.storage.data(), rp_.mass.data(), rp_.limited.data(), rp_.limitFactor.data());
        rp_.t = solver_.time(); rp_.dt = solver_.dtBase(); rp_.used = 0; rp_.valid = true;
    }
    // ResetBasedOnRestorePoint: restart at a fifth of the step and hold it
    // there with a ceiling, or the oscillation returns within ten steps.
    bool resetToRestorePoint() {
        const auto& S = solver_.settings();
        if (!rp_.valid || rp_.used >= S.restore_point_max_uses) return false;
        importState(rp_.t, rp_.storage.data(), rp_.mass.data(), rp_.limited.data(), rp_.limitFactor.data());
        rp_.used++;
        const double dtn = rp_.dt / 5.0;
        solver_.setDtBase(dtn); solver_.setDtCeiling(dtn);
        clean_steps_ = 0;
        knockoutOutputs(rp_.t);
        rp_.dt = dtn;
        return true;
    }
    // TimeSeriesSet::knockout -- drop the samples the rewind invalidated.
    void knockoutOutputs(double tcut) {
        for (auto& s : obs_) {
            ohq::TimeSeries kept;
            for (std::size_t k = 0; k < s.size(); ++k)
                if (s.t[k] <= tcut) kept.push(s.t[k], s.c[k]);
            s = kept;
        }
    }
    // CountOscillatingStates: increments that alternate in sign and are not
    // all negligible against the local magnitude (TimeSeries::wiggle_sl).
    int countOscillatingStates(double tol) {
        std::vector<double> x; gatherSolvedState(x);
        osc_history_.push_back(x);
        if (osc_history_.size() > 4) osc_history_.erase(osc_history_.begin());
        if (osc_history_.size() < 4) return 0;
        const std::vector<double>& c4 = osc_history_[0];
        const std::vector<double>& c3 = osc_history_[1];
        const std::vector<double>& c2 = osc_history_[2];
        const std::vector<double>& c1 = osc_history_[3];
        const std::size_t n = c1.size();
        if (c2.size() != n || c3.size() != n || c4.size() != n) return 0;
        int count = 0;
        for (std::size_t i = 0; i < n; ++i) {
            const double scale = (std::fabs(c1[i]) + std::fabs(c2[i]) + std::fabs(c3[i])
                                  + std::fabs(c4[i])) / 4.0 + tol / 100.0;
            if (scale <= 0) continue;
            const double d1 = (c1[i] - c2[i]) / scale;
            const double d2 = (c2[i] - c3[i]) / scale;
            const double d3 = (c3[i] - c4[i]) / scale;
            const bool all_small   = std::fabs(d1) < tol && std::fabs(d2) < tol && std::fabs(d3) < tol;
            const bool alternating = (d1 * d2 < 0) && (d2 * d3 < 0);
            if (!all_small && alternating) count++;
        }
        return count;
    }
    // Run after an accepted step, in System::Solve's order: relax an existing
    // ceiling first, then test for oscillation.
    void oscillationControl() {
        const auto& S = solver_.settings();
        if (solver_.dtCeiling() > 0 && S.oscillation_relax_after > 0) {
            if (++clean_steps_ >= S.oscillation_relax_after) {
                clean_steps_ = 0;
                solver_.setDtCeiling(solver_.dtCeiling() * 2.0);
                osc_relaxations_++;
                if (osc_reductions_ > 0) osc_reductions_--;
                if (solver_.dtCeiling() >= dt0_ * S.dt_max_factor) solver_.setDtCeiling(0.0);
            }
        }
        if (!S.oscillation_control) return;
        if (stepCounter_ <= 4 || stepCounter_ - osc_last_counter_ <= 4) return;   // cooldown
        const int nosc = countOscillatingStates(S.oscillation_tolerance);
        if (nosc <= 0) return;
        clean_steps_ = 0;
        const bool budget_left = osc_reductions_ < S.oscillation_max_reductions;
        bool acted = false;
        if (budget_left && S.oscillation_rewind) acted = resetToRestorePoint();
        else if (budget_left) {
            const double dtn = solver_.dtBase() / 5.0;
            solver_.setDtBase(dtn); solver_.setDtCeiling(dtn);
            clean_steps_ = 0;
            acted = true;
        }
        if (acted) {
            osc_reductions_++; osc_events_++;
            osc_last_counter_ = stepCounter_;
            osc_history_.clear();          // the state jumped backwards
            solver_.requestJacobianUpdate();
            transport_.requestJacobianUpdate();
        } else if (!osc_gave_up_) {
            osc_gave_up_ = true;           // budget exhausted; report once
        }
    }

